<template>
  <q-page class="critical-status-page q-pa-md">
    <!-- ══ Header ══ -->
    <div class="row items-start justify-between q-col-gutter-md q-mb-md">
      <div class="col-12 col-md">
        <div class="row items-center q-gutter-sm">
          <h4 class="page-title q-my-none">Critical Test Status</h4>
          <q-chip
            :style="{ background: environmentColor, color: '#fff' }"
            size="sm"
            dense
            class="text-weight-bold"
          >
            {{ environment.toUpperCase() }}
          </q-chip>
          <!-- Named by its branch line, never as a bare "VESTA"/"NOVA": these
               track values and the app's `vesta`/`nova` release channels now
               agree (DEVO-135), but the branch line is still the more precise
               label since a track spans multiple release-channel orgs. See
               trackLabel(). -->
          <q-chip :class="['track-chip', `track-chip--${track}`]" size="sm" dense square>
            {{ trackText }}
          </q-chip>
        </div>
        <div class="page-subtitle">
          Deploy-blocking gate per service, from Prometheus
          <template v-if="lastFetchedAt"> · updated {{ formatDateTime(lastFetchedAt) }}</template>
          <span v-if="refreshing" class="refresh-hint">
            <q-spinner size="11px" class="q-mr-xs" />refreshing
          </span>
          <span v-else class="refresh-hint">
            · auto-refreshes every {{ autoRefreshMinutes }} min
          </span>
        </div>
      </div>

      <div class="col-12 col-md-auto row items-center q-gutter-sm justify-end">
        <q-btn
          outline
          no-caps
          dense
          icon="table_rows"
          label="Service overview"
          class="q-px-sm"
          to="/tests/overview"
        />
        <q-btn
          unelevated
          no-caps
          dense
          color="primary"
          icon="refresh"
          label="Refresh"
          class="q-px-sm"
          :loading="loading || refreshing"
          @click="fetchStatuses()"
        />
      </div>
    </div>

    <!-- ══ Release track ══ -->
    <!-- One track at a time, on purpose: the estate merge below keys placeholders
         on the service alone, so mixing both lines would let a service reporting
         on VESTA mask a missing NOVA verdict. -->
    <div class="track-bar q-mb-md">
      <q-btn-toggle
        v-model="track"
        :options="trackOptions"
        no-caps
        dense
        unelevated
        toggle-color="primary"
        color="grey-3"
        text-color="grey-8"
        class="track-toggle"
      />
      <div class="track-bar__hint">
        <strong>Branch line, not release channel.</strong> VESTA is the
        <code>dev</code> / <code>stage</code> / <code>prod</code> branch line; NOVA is their
        <code>-nova</code> twins. Both deploy the same services into the same environments, so a
        verdict only means something with its line attached. These are the CI collector's
        <code>track</code> values — since DEVO-135 they agree with the release channels under
        Settings → Company → Release Channel (<code>vesta</code>/<code>nova</code>), but a track
        spans every org on that branch line regardless of channel, so the branch-line label
        stays the precise one here.
      </div>
    </div>

    <!-- A track nothing reports on is a fact, not a fault. Said plainly, so that
         a screen of grey placeholder rows is not misread as a fleet-wide gap. -->
    <q-banner v-if="!loading && trackReports === 0" class="track-note q-mb-md" rounded dense>
      <template #avatar><q-icon name="info" size="20px" /></template>
      <strong>No service reports a {{ trackText }} gate yet.</strong>
      <template v-if="track === 'nova'">
        The <code>-nova</code> branches have no gate-reporting pipeline, so nothing publishes a
        verdict for this line. Every row below is "no gate metric" for that reason — not a failing
        or a regressed gate. The first {{ trackText }} row appearing here is the signal that a
        NOVA pipeline started reporting.
      </template>
      <template v-else>
        Nothing has published a verdict for this line inside the {{ metricWindow }} read window.
      </template>
    </q-banner>

    <!-- ══ Verdict banner ══ -->
    <div
      v-if="!loading && visibleStatuses.length > 0"
      id="critical-status-verdict-banner"
      :class="['verdict', verdictClass]"
    >
      <q-icon :name="failingStatuses.length > 0 ? 'block' : 'verified'" size="26px" />
      <div class="verdict__body">
        <div class="verdict__title">
          <template v-if="failingStatuses.length > 0">
            Deploy blocked — {{ failingStatuses.length }}
            {{
              failingStatuses.length === 1
                ? 'service is failing its'
                : 'services are failing their'
            }}
            critical tests on {{ trackText }}
          </template>
          <template v-else>
            No service is failing its critical-test gate on {{ trackText }}
          </template>
        </div>
        <div v-if="failingStatuses.length > 0" class="verdict__chips">
          <button
            v-for="status in failingStatuses"
            :key="rowKey(status)"
            type="button"
            class="verdict__chip"
            @click="focusRow(status)"
          >
            {{ displayName(status.service) }}
            <strong v-if="status.counts.failed > 0">{{ status.counts.failed }} failed</strong>
          </button>
        </div>
      </div>
    </div>

    <!-- ══ KPI strip (each tile filters the table) ══ -->
    <div class="kpi-strip q-mb-md">
      <div
        v-for="kpi in kpis"
        :id="`critical-status-kpi-${kpi.states[0]}`"
        :key="kpi.label"
        :class="[
          'kpi',
          `kpi--${kpi.states[0]}`,
          { 'kpi--active': stateFilter?.label === kpi.label },
        ]"
        role="button"
        tabindex="0"
        @click="toggleStateFilter(kpi)"
        @keydown.enter="toggleStateFilter(kpi)"
        @keydown.space.prevent="toggleStateFilter(kpi)"
      >
        <div class="kpi__label">
          <q-icon :name="kpi.icon" size="14px" />
          {{ kpi.label }}
        </div>
        <div class="kpi__value">
          <span v-if="kpi.states[0] === 'failing' && kpi.count > 0" class="pulse-dot"></span>
          {{ kpi.count }}
        </div>
        <div class="kpi__foot">{{ kpi.hint }}</div>
      </div>
    </div>

    <!-- ══ Error ══ -->
    <q-banner v-if="error" class="bg-negative text-white q-mb-md" rounded dense>
      <template #avatar><q-icon name="error" /></template>
      {{ error }}
      <template #action>
        <q-btn flat dense no-caps label="Retry" @click="fetchStatuses()" />
      </template>
    </q-banner>

    <!-- ══ Filters ══ -->
    <div class="filter-row q-mb-sm">
      <q-input
        v-model="search"
        dense
        outlined
        clearable
        debounce="200"
        placeholder="Search service…"
        class="filter-row__search"
      >
        <template #prepend><q-icon name="search" size="18px" /></template>
      </q-input>

      <q-toggle v-model="showUnreported" dense size="sm" label="Show services without metrics" />

      <q-btn
        v-if="stateFilter"
        flat
        dense
        no-caps
        size="sm"
        icon="close"
        :label="`Clear ${stateFilter.label} filter`"
        @click="stateFilter = null"
      />

      <q-space />
      <div class="filter-row__count">{{ visibleStatuses.length }} of {{ statuses.length }}</div>
    </div>

    <!-- ══ Table ══ -->
    <q-table
      v-model:pagination="pagination"
      :rows="visibleStatuses"
      :columns="columns"
      :row-key="rowKey"
      flat
      bordered
      dense
      :loading="loading"
      :wrap-cells="false"
      :rows-per-page-options="[15, 30, 50, 0]"
      class="gate-table"
    >
      <template #loading>
        <q-inner-loading showing color="primary" />
      </template>

      <template #no-data>
        <div class="full-width column flex-center q-py-xl text-muted">
          <q-icon name="search_off" size="28px" class="q-mb-sm" />
          <div v-if="statuses.length > 0">
            All {{ statuses.length }} entries are hidden by the current filters.
          </div>
          <div v-else>
            Prometheus returned no critical-test series for
            <strong>{{ environment }}</strong> on <strong>{{ trackText }}</strong>.
          </div>
        </div>
      </template>

      <template #body="props">
        <q-tr
          :id="rowKey(props.row)"
          :props="props"
          :class="[
            `row--${state(props.row)}`,
            { 'row--flash': flashed === rowKey(props.row) },
          ]"
        >
          <q-td v-for="col in props.cols" :key="col.name" :props="props">
            <!-- Service -->
            <template v-if="col.name === 'service'">
              <div class="service-cell">
                <span :class="['state-dot', `state-dot--${state(props.row)}`]"></span>
                <div>
                  <div class="service-cell__name">{{ displayName(props.row.service) }}</div>
                  <div class="service-cell__repo">
                    {{ props.row.repo || props.row.service }}
                  </div>
                </div>
              </div>
            </template>

            <!-- Status -->
            <template v-else-if="col.name === 'status'">
              <span :class="['status-pill', `status-pill--${state(props.row)}`]">
                <q-icon :name="info(state(props.row)).icon" size="13px" />
                {{ info(state(props.row)).label }}
                <q-tooltip anchor="top middle" self="bottom middle" max-width="320px">
                  {{ info(state(props.row)).explain }}
                </q-tooltip>
              </span>
            </template>

            <!-- Counts -->
            <template v-else-if="col.name === 'failed'">
              <span v-if="!props.row.hasMetrics" class="text-muted">—</span>
              <span v-else-if="props.row.counts.failed > 0" class="failed-badge">
                <span class="pulse-dot pulse-dot--light"></span>
                {{ props.row.counts.failed }}
              </span>
              <span v-else class="text-muted">0</span>
            </template>

            <template v-else-if="col.name === 'totalTests'">
              <span :class="props.row.totalTests > 0 ? 'value-strong' : 'text-muted'">
                {{ props.row.hasMetrics ? props.row.totalTests : '—' }}
              </span>
            </template>

            <!-- Reported: the verdict's age, beside the verdict and never inside
                 it. Neutral by design — several services deploy about once a week,
                 so "6d ago" is information, not a warning. -->
            <template v-else-if="col.name === 'lastRun'">
              <span :class="['age-chip', { 'age-chip--none': !hasReported(props.row) }]">
                {{ relativeAge(props.row.finishedAt) }}
                <q-tooltip v-if="hasReported(props.row)" anchor="top middle" self="bottom middle">
                  {{ formatDateTime(props.row.finishedAt) }}
                </q-tooltip>
              </span>
            </template>

            <!-- Build -->
            <template v-else-if="col.name === 'build'">
              <div class="build-cell">
                <span v-if="props.row.imageTag" class="meta-chip">v{{ props.row.imageTag }}</span>
                <span v-if="props.row.commit" class="meta-chip meta-chip--mono">
                  {{ props.row.commit }}
                </span>
                <span v-if="!props.row.imageTag && !props.row.commit" class="text-muted">—</span>
              </div>
            </template>

            <!-- Actions -->
            <template v-else-if="col.name === 'actions'">
              <div class="row no-wrap items-center justify-end">
                <q-btn
                  v-if="runLink(props.row)"
                  flat
                  dense
                  round
                  size="sm"
                  icon="open_in_new"
                  :href="runLink(props.row)!"
                  target="_blank"
                  rel="noopener"
                >
                  <q-tooltip>Open CI run</q-tooltip>
                </q-btn>
                <q-btn
                  v-if="webKey(props.row.service)"
                  flat
                  dense
                  round
                  size="sm"
                  icon="science"
                  :to="`/tests/${webKey(props.row.service)}`"
                >
                  <q-tooltip>Full test results</q-tooltip>
                </q-btn>
              </div>
            </template>

            <template v-else>{{ col.value }}</template>
          </q-td>
        </q-tr>

        <!-- Inline caveat row: green verdicts that should not be read as green -->
        <q-tr v-if="caveat(props.row)" :props="props" class="caveat-tr">
          <q-td :colspan="props.cols.length" class="caveat-td">
            <q-icon name="warning" size="13px" class="q-mr-xs" />
            {{ caveat(props.row) }}
          </q-td>
        </q-tr>
      </template>
    </q-table>
  </q-page>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { date } from 'quasar';
import type { QTableColumn } from 'quasar';
import {
  DEFAULT_TRACK,
  METRIC_WINDOW,
  RELEASE_TRACKS,
  SERVICE_DEFINITIONS,
  criticalTestsPrometheusService,
  gateRank,
  gateState,
  mergeWithKnownServices,
  runUrl,
  serviceDisplayName,
  serviceWebKey,
  statusesForTrack,
  trackLabel,
  trackReportCounts,
  type CriticalGateState,
  type ReleaseTrack,
  type ServiceCriticalStatus,
} from 'src/services/tests';
import { logger } from 'src/utils/logger';

/** How often the page re-queries Prometheus on its own. */
const AUTO_REFRESH_MS = 5 * 60 * 1000;

/**
 * Everything that varies per gate state, in one place — label, icon and the
 * hover explanation. Purely presentational: the ORDER these states carry lives
 * in GATE_ORDER in the service, so the board's default grouping and the Gate
 * status column's sort cannot drift apart from each other.
 */
const GATE_STATES: Record<CriticalGateState, { label: string; icon: string; explain: string }> = {
  failing: {
    label: 'Failing',
    icon: 'block',
    explain: 'The critical-test gate reported failure. Deploys for this service are blocked.',
  },
  'no-tests': {
    label: 'No critical tests',
    icon: 'help_outline',
    explain:
      'The gate reported success but ran no critical tests, so this is not evidence that the service works.',
  },
  'not-configured': {
    label: 'Not configured',
    icon: 'remove_circle_outline',
    explain: 'The service pushes metrics but reports its gate as not configured.',
  },
  passing: {
    label: 'Passing',
    icon: 'verified',
    explain: 'Every critical test passed.',
  },
  'no-metrics': {
    label: 'No gate metric',
    icon: 'cloud_off',
    explain:
      'This service publishes no critical-test metrics to Prometheus yet, so its gate status is unknown.',
  },
};

/**
 * KPI tiles. Each tile filters the table to the states it counts — so the
 * "No gate metric" tile, which rolls up two states, filters to both.
 *
 * There is deliberately no age tile. A "Stale" tile counted verdicts older than
 * 24h as a problem, which for a fleet where several services deploy weekly meant
 * a permanent non-zero count describing nothing wrong. Age now lives in the
 * Reported column, next to each verdict, where it is a fact about one row rather
 * than a fleet-wide alarm.
 */
const KPI_TILES: {
  label: string;
  icon: string;
  hint: string;
  states: CriticalGateState[];
}[] = [
  { label: 'Blocking deploys', icon: 'block', hint: 'gate reported failure', states: ['failing'] },
  { label: 'Green', icon: 'verified', hint: 'critical tests all passed', states: ['passing'] },
  {
    label: 'No critical tests',
    icon: 'help_outline',
    hint: 'green, but nothing ran',
    states: ['no-tests'],
  },
  {
    label: 'No gate metric',
    icon: 'cloud_off',
    hint: 'not reporting to Prometheus',
    states: ['no-metrics', 'not-configured'],
  },
];

type KpiTile = (typeof KPI_TILES)[number];

export default defineComponent({
  name: 'CriticalStatusPage',

  data() {
    return {
      /**
       * Every row Prometheus returned, both release lines together. One request
       * covers both, so switching track is a filter rather than a refetch — and
       * it is the only way the page can say that a track reports nothing at all.
       */
      reported: [] as ServiceCriticalStatus[],
      /** Release line on show. VESTA first: it is the line that ships today. */
      track: DEFAULT_TRACK,
      loading: false,
      /** Background refresh in flight — deliberately separate from `loading`, which swaps the table out */
      refreshing: false,
      refreshTimer: null as number | null,
      error: null as string | null,
      lastFetchedAt: null as Date | null,
      search: '' as string | null,
      showUnreported: true,
      stateFilter: null as KpiTile | null,
      flashed: null as string | null,
      /**
       * `sortBy: null` is the board's own default order, not the absence of one.
       * QTable renders rows exactly as given while no column is sorted, so the
       * order set by sortForBoard() — attention first, then blocking test-case
       * count descending — is what a reader sees on arrival. Clicking any header
       * hands sorting to QTable, and its third click returns here.
       */
      pagination: { rowsPerPage: 30, sortBy: null as string | null, descending: false },
    };
  },

  computed: {
    /**
     * The environment this dashboard reports on. Not user-selectable: the page
     * always shows the estate for the deployment it is running in. Both
     * deployment workflows fail the build when APP_VUE_STAGE is empty, so it is
     * always set here.
     */
    environment(): string {
      return process.env.APP_VUE_STAGE;
    },

    autoRefreshMinutes(): number {
      return Math.round(AUTO_REFRESH_MS / 60_000);
    },

    metricWindow(): string {
      return METRIC_WINDOW;
    },

    /**
     * The table's rows: the selected track's verdicts, plus a placeholder for
     * every service in the app's registry that this track is silent about.
     *
     * Narrowing to one track BEFORE the merge is what makes the placeholders
     * mean anything. mergeWithKnownServices keys coverage on the service name
     * alone, so handed both lines at once it would treat a VESTA-only reporter as
     * covered and quietly swallow the missing NOVA verdict.
     *
     * Comes back in the board's default order (sortForBoard) — the filters below
     * preserve it, and QTable renders it as given until a header is clicked.
     */
    statuses(): ServiceCriticalStatus[] {
      return mergeWithKnownServices(
        statusesForTrack(this.reported, this.track),
        SERVICE_DEFINITIONS.map((definition) => definition.service),
        this.environment,
        this.track
      );
    },

    /** Services actually reporting per track — never placeholders. */
    reportsPerTrack(): Record<ReleaseTrack, number> {
      return trackReportCounts(this.reported);
    },

    /** How many services report on the selected track. Zero is a fact, not a fault. */
    trackReports(): number {
      return this.reportsPerTrack[this.track];
    },

    /** The selected line, named by its branch so it cannot be read as a channel. */
    trackText(): string {
      return trackLabel(this.track, this.environment);
    },

    /**
     * The track switch, each option carrying how many services report on it — so
     * a line nothing publishes for is visible before it is selected, rather than
     * looking like an empty board once it is.
     *
     * Labelled `VESTA (dev) · 12`, not `VESTA · 12`: the branch is the part that
     * says which line this is, since the app's release channels carry the same two
     * names for the opposite thing. See trackLabel().
     */
    trackOptions(): { label: string; value: ReleaseTrack }[] {
      return RELEASE_TRACKS.map((value) => ({
        label: `${trackLabel(value, this.environment)} · ${this.reportsPerTrack[value]}`,
        value,
      }));
    },

    environmentColor(): string {
      const colorMap: Record<string, string> = {
        dev: '#2563eb',
        stage: '#f59e0b',
        prod: '#dc2626',
        demo: '#9333ea',
        sandbox: '#0d9488',
      };
      return colorMap[this.environment] || '#64748b';
    },

    columns(): QTableColumn<ServiceCriticalStatus>[] {
      return [
        {
          name: 'service',
          label: 'Service',
          field: (row) => serviceDisplayName(row.service),
          align: 'left',
          sortable: true,
        },
        {
          name: 'status',
          label: 'Gate status',
          // Sorted by the service's own state ranking, so this column and the
          // board's default grouping cannot disagree about what comes first.
          field: (row) => gateRank(gateState(row)),
          align: 'left',
          sortable: true,
        },
        {
          // Sits next to the verdict on purpose: a verdict without its age is not
          // a status. Sortable, so "what has not reported lately" is one click
          // away — without any row being called stale for it.
          name: 'lastRun',
          label: 'Reported',
          field: (row) => row.finishedAt.getTime(),
          align: 'left',
          sortable: true,
        },
        { name: 'failed', label: 'Failed', field: (row) => row.counts.failed, align: 'right', sortable: true },
        {
          // The magnitude the default order runs on. "Blocking" is not decoration:
          // these are the cases that can stop a deployment, not the service's whole
          // suite, so the numbers are not comparable as quality — see sortForBoard().
          name: 'totalTests',
          label: 'Blocking cases',
          field: 'totalTests',
          align: 'right',
          sortable: true,
        },
        { name: 'build', label: 'Build', field: 'imageTag', align: 'left', sortable: false },
        { name: 'actions', label: '', field: 'service', align: 'right', sortable: false },
      ];
    },

    visibleStatuses(): ServiceCriticalStatus[] {
      const term = (this.search || '').trim().toLowerCase();

      return this.statuses.filter((status) => {
        if (!this.showUnreported && !status.hasMetrics) return false;
        if (this.stateFilter && !this.stateFilter.states.includes(this.state(status)))
          return false;
        if (term) {
          const haystack =
            `${status.service} ${this.displayName(status.service)} ${status.repo ?? ''}`.toLowerCase();
          if (!haystack.includes(term)) return false;
        }
        return true;
      });
    },

    failingStatuses(): ServiceCriticalStatus[] {
      return this.visibleStatuses.filter((status) => this.state(status) === 'failing');
    },

    verdictClass(): string {
      return this.failingStatuses.length > 0 ? 'verdict--blocked' : 'verdict--clear';
    },

    kpis(): (KpiTile & { count: number })[] {
      const tally = new Map<CriticalGateState, number>();
      this.visibleStatuses.forEach((status) => {
        const state = this.state(status);
        tally.set(state, (tally.get(state) ?? 0) + 1);
      });

      return KPI_TILES.map((tile) => ({
        ...tile,
        count: tile.states.reduce((sum, state) => sum + (tally.get(state) ?? 0), 0),
      }));
    },
  },

  mounted() {
    this.fetchStatuses();
    this.refreshTimer = window.setInterval(() => {
      // Skip the tick while the tab is hidden — no point querying a dashboard
      // nobody is looking at. The interval itself is free.
      if (!document.hidden) {
        void this.fetchStatuses(true);
      }
    }, AUTO_REFRESH_MS);
  },

  beforeUnmount() {
    // Vue Router unmounts this component on route change (no <keep-alive> in the
    // layouts), so this is the only cleanup hook needed.
    if (this.refreshTimer !== null) {
      window.clearInterval(this.refreshTimer);
    }
  },

  methods: {
    /**
     * @param silent - background refresh: keeps the current table on screen
     *   instead of swapping in the loading state, and keeps the last good data
     *   if the request fails.
     */
    async fetchStatuses(silent = false): Promise<void> {
      // Never let a tick overlap an in-flight request
      if (this.loading || this.refreshing) {
        return;
      }

      if (silent) {
        this.refreshing = true;
      } else {
        this.loading = true;
        this.error = null;
      }

      try {
        // Both release lines in one request; the estate merge and the split by
        // track happen in `statuses`, so the switch needs no round trip.
        this.reported = await criticalTestsPrometheusService.getCriticalStatuses(this.environment);
        this.lastFetchedAt = new Date();
        this.error = null;
      } catch (err) {
        logger.error('[CriticalStatusPage] Failed to load gate metrics:', err);
        this.error = silent
          ? 'Auto-refresh could not reach Prometheus. Showing the last successful result.'
          : 'Could not reach Prometheus. Please try again.';
        // A failed background refresh must not blank a table someone is reading.
        // The "updated" timestamp still shows when the data was actually current.
        if (!silent) {
          this.reported = [];
        }
      } finally {
        this.loading = false;
        this.refreshing = false;
      }
    },

    state(status: ServiceCriticalStatus): CriticalGateState {
      return gateState(status);
    },

    /** Label, icon and hover explanation for a row's state. */
    info(state: CriticalGateState): { label: string; icon: string; explain: string } {
      return GATE_STATES[state];
    },

    /** Inline warning for verdicts that look green but should not be trusted. */
    caveat(status: ServiceCriticalStatus): string | null {
      if (this.state(status) === 'no-tests') {
        return 'Gate reports success but ran no critical tests — not a genuine pass.';
      }
      if (status.passed && status.counts.failed > 0) {
        return `Gate reports success despite ${status.counts.failed} failed ${
          status.counts.failed === 1 ? 'test' : 'tests'
        }.`;
      }
      return null;
    },

    displayName(service: string): string {
      return serviceDisplayName(service);
    },

    webKey(service: string): string | null {
      return serviceWebKey(service);
    },

    runLink(status: ServiceCriticalStatus): string | null {
      return runUrl(status);
    },

    rowKey(status: ServiceCriticalStatus): string {
      // `track` belongs in the key even though the table shows one line at a
      // time: it is the row IDENTITY, and the DOM id is what focusRow() scrolls
      // to. Two lines' rows for one service must never collide.
      return `gate-${status.service}-${status.environment}-${status.track}`.replace(
        /[^a-zA-Z0-9-]/g,
        '-'
      );
    },

    /** Whether this row has a push timestamp at all, as opposed to how old it is. */
    hasReported(status: ServiceCriticalStatus): boolean {
      return status.hasMetrics && status.finishedAt.getTime() > 0;
    },

    toggleStateFilter(tile: KpiTile): void {
      this.stateFilter = this.stateFilter?.label === tile.label ? null : tile;
    },

    focusRow(status: ServiceCriticalStatus): void {
      const key = this.rowKey(status);
      this.stateFilter = null;
      this.$nextTick(() => {
        document.getElementById(key)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        this.flashed = key;
        window.setTimeout(() => {
          if (this.flashed === key) this.flashed = null;
        }, 1600);
      });
    },

    relativeAge(value: Date): string {
      if (!value || value.getTime() === 0) return 'never';
      const minutes = Math.round((Date.now() - value.getTime()) / 60_000);
      if (minutes < 1) return 'just now';
      if (minutes < 60) return `${minutes}m ago`;
      const hours = Math.round(minutes / 60);
      if (hours < 24) return `${hours}h ago`;
      return `${Math.round(hours / 24)}d ago`;
    },

    formatDateTime(value: Date): string {
      return date.formatDate(value, 'MMM D, YYYY HH:mm');
    },
  },
});
</script>

